// Generated by `npm run calibrate -- --stage probe --write`. Do not edit by hand:
// rerun calibration and review the diff (docs/how-to/calibrate-rendering.md).
// Every engine reads these rules so HTML/SVG/PDF place text where PowerPoint does.

export interface OfficeRules {
  renderer: string;
  calibratedAt: string;
  /** Glyph advances snap to 1/unitsPerInch; pair kerning snaps too only when snapKerning. */
  advance: { unitsPerInch: number; snapKerning: boolean };
  /** Size glyph outlines are drawn at: 'whole-point' rounds half up, 'nominal' keeps it. */
  drawSize: 'whole-point' | 'nominal';
  /** Height PowerPoint centres or bottom-aligns: every line's full pitch ('pitch'), or
   * up to the last line's descent ('ink'). */
  anchorHeight: 'pitch' | 'ink';
  /** Where anchored baselines round to whole points: after the shift ('total'), shift and
   * offset separately ('shift'), or only the offset ('none'). */
  anchorRounding: 'none' | 'total' | 'shift';
  /** Descent (em) of the real Office font where the measuring substitute differs. */
  descentEmByFamily: Record<string, number>;
  /** Automatic and percentage (multiple m) spacing: pitch = pitchEm × size × m. First
   * baseline: m ≤ 1 keeps the descent, pitch − (1 − ratio) × pitchEm × size, where ratio is
   * calibrated per family or taken from the font ('hhea' ascent share); m > 1 puts it at
   * aboveOneFraction × pitch for every font. */
  autoSpacing: {
    pitchEm: Record<string, number>;
    aboveOneFraction: number;
    ratio: 'hhea' | 'typo';
    ratioByFamily: Record<string, number>;
    /** Baselines sit on multiples of this many points below the text top (0 = continuous). */
    snapPt: number;
  };
  /** Exact (point) spacing: pitch snaps to snapPitchPt; first baseline = pitch × ratio
   * ('typo' ascent share of the font, or calibrated per family), or the centred font box. */
  exactSpacing: {
    /** How generated (not source-authored) point spacing is written to PPTX. */
    export: 'percent' | 'points';
    ratio: 'typo' | 'hhea' | 'centered';
    ratioByFamily: Record<string, number>;
    snapPitchPt: number;
    snapPt: number;
  };
}

